package org.ubuntuquest.pocket;
import android.os.Bundle;
import android.content.SharedPreferences;
import android.widget.*;
public final class InteractionSettingsActivity extends InteractionActivity {
 private SettingsUi ui;private LinearLayout body;
 public void onCreate(Bundle b){super.onCreate(b);ui=new SettingsUi(this);SystemBarFrame frame=new SystemBarFrame(this);frame.setBackground(new WallpaperDrawable(this,"launcher"));LinearLayout page=ui.column();frame.addView(page);page.addView(ui.header("Device layout & input",this::finish,null));ScrollView scroll=new ScrollView(this);body=ui.column();body.setPadding(ui.dp(14),0,ui.dp(14),0);scroll.addView(body);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(frame);render();}
 private void render(){body.removeAllViews();SharedPreferences p=DeviceProfiles.settings(this);LinearLayout profile=ui.card(body,"Your workspace");profile.addView(ui.text(DeviceProfiles.label(DeviceProfiles.current(this))+" · "+(DeviceProfiles.pointer()?"Pointer connected":"Touch / controller")+(DeviceProfiles.keyboard()?" · Keyboard connected":""),15,false));String[] profileIds=DeviceProfilePolicy.IDS,profileLabels=new String[profileIds.length];int profileIndex=0;for(int i=0;i<profileIds.length;i++){profileLabels[i]=DeviceProfiles.label(profileIds[i]);if(profileIds[i].equals(p.getString("profile","auto")))profileIndex=i;}ui.choiceRow(profile,"device-layout","Device layout",profileLabels,profileIndex,index->{p.edit().putString("profile",profileIds[index]).apply();DeviceProfiles.changed(this);recreate();});profile.addView(ui.text("Each device layout keeps its own category, folder, favorite and widget arrangement. New profiles begin with a copy of your existing layout.",13,true));
  LinearLayout input=ui.card(body,"Controls");String[] sizes={"auto","touch","compact"};int sizeIndex=java.util.Arrays.asList(sizes).indexOf(p.getString("controls","auto"));ui.choiceRow(input,"control-size","Control size",new String[]{"Automatic","Comfortable touch","Compact pointer"},Math.max(0,sizeIndex),index->{p.edit().putString("controls",sizes[index]).apply();DeviceProfiles.changed(this);recreate();});input.addView(ui.text("Alt+Space · Find an action\nCtrl+Alt+R · Running apps\nCtrl+Alt+S · Status & controls\nRight-click an app for its quick actions.",14,true));
  LinearLayout controller=ui.card(body,"Controllers & foldable screens");
  controller.addView(ui.text("D-pad / left stick: move focus\nA: select · B: back\nX: focused item actions · Y / Start: workspace actions\nLB / RB: previous / next control",14,false));
  controller.addView(ui.text("In Ubuntu: D-pad / left stick sends arrow keys, A sends Enter, B sends Escape, and X opens the keyboard. Existing Quest mouse-button controls take priority when enabled. Menus keep controller input inside the menu.",13,true));
  controller.addView(ui.text("Folding and unfolding reflows the current screen. A separating vertical hinge uses the larger pane; tabletop uses the upper pane. Fully open, non-occluding displays use the full window. Your Ubuntu session keeps running. Devices without hinge reports still adapt to window size.",13,true));
  LinearLayout drawer=ui.card(body,"Action drawer");drawer.addView(ui.toggle("Show action handle in Ubuntu desktop",p.getBoolean("bottom-actions",true),on->p.edit().putBoolean("bottom-actions",on).apply()));drawer.addView(ui.text("Launcher actions are in Settings. This handle applies only while viewing Ubuntu. Changes apply when returning to that screen.",13,true));
  LinearLayout gestures=ui.card(body,"Inner-edge gestures");gestures.addView(ui.toggle("Enable within Droibuntu",p.getBoolean("edges",false),on->p.edit().putBoolean("edges",on).apply()));gestures.addView(ui.text("Swipe inward from just inside either side. Android’s outer gesture strip stays available. Disabled while a screen reader explores by touch.",13,true));for(String side:new String[]{"left","right"})gestures.addView(ui.button((side.equals("left")?"Left":"Right")+": "+InteractionActions.label(p.getString("edge-"+side,side.equals("left")?"apps":"running")),null,()->chooseGesture(side)));
  TextView distance=ui.text("Swipe distance: "+p.getInt("edge-distance",96)+" dp",14,true);gestures.addView(distance);SeekBar slider=new SeekBar(this);slider.setMax(96);slider.setProgress(Math.max(0,p.getInt("edge-distance",96)-64));slider.setContentDescription("Gesture swipe distance");gestures.addView(slider);slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){p.edit().putInt("edge-distance",64+s.getProgress()).apply();}public void onProgressChanged(SeekBar s,int v,boolean user){distance.setText("Swipe distance: "+(64+v)+" dp");}});
  LinearLayout previews=ui.card(body,"Window previews");previews.addView(ui.toggle("Preview Ubuntu windows in Running apps",p.getBoolean("window-previews",false),on->{p.edit().putBoolean("window-previews",on).apply();if(!on)WindowPreview.clear(this);}));previews.addView(ui.text("Optional small images of Ubuntu windows. Stored temporarily inside Droibuntu and hidden while the device is locked. Android apps use their icons.",13,true));
  body.addView(ui.button("VR comfort & controllers",null,()->startActivity(new android.content.Intent(this,VrSettingsActivity.class))));
  body.addView(ui.button("Ubuntu tile size & VR comfort",null,()->startActivity(new android.content.Intent(this,DesktopExperienceActivity.class))));
  body.addView(ui.button("Status & controls",null,()->InteractionActions.run(this,"status")));
 }
 private void profiles(){LauncherMenuSheet m=new LauncherMenuSheet(this,"Device layout");for(String id:DeviceProfilePolicy.IDS)m.choice(DeviceProfiles.label(id),"ic_menu_check",id.equals(DeviceProfiles.settings(this).getString("profile","auto")),()->{DeviceProfiles.settings(this).edit().putString("profile",id).apply();DeviceProfiles.changed(this);recreate();});m.show();}
 private void chooseGesture(String side){LauncherMenuSheet m=new LauncherMenuSheet(this,"Choose "+side+" gesture");for(String id:InteractionActions.GESTURES)m.action(InteractionActions.label(id),"ic_menu_check",()->{DeviceProfiles.settings(this).edit().putString("edge-"+side,id).apply();render();});m.show();}
}
